ee:message.ee:set-payload:
%dw 2.0
output application/json
import * from dw::Runtime
var ind = vars.counter - 1
var docTest = try(() -> payload[ind])
var doc = if (docTest.success) docTest.result else payload
---
if (payload is String) {
	fileName:  payload,
	fileContent: vars.inputAttachments[payload]
}
else {
	fileName:  doc,
	fileContent: vars.inputAttachments[doc]
}

%dw 2.0
output application/json
import * from dw::core::Strings
---
//0002
if (vars.mensajeAbdFinal.MensajeABD.CabeceraMensaje.TipoMsg == "0002")
{
    WSRequestSolicitudSincronizacionABD: {
        PortabilidadMsg: {
            CabeceraMensaje: {
                Identificador: vars.idIntegration,
                TipoDeMensaje: vars.mensajeAbdFinal.MensajeABD.CabeceraMensaje.TipoMsg
            },
            CuerpoMensaje: {
                RespuestaSolicitudPortacionDonante: {
                    (ListaNumeracionRechazada: {
                        NumeracionRechazada: vars.mensajeAbdFinal.MensajeABD.CuerpoMensaje.RespuestaSolicitudNIP.NumeracionRechazada map ((it, in) -> {
                            CodigosRechazo: {
                                CodigoRechazo: it.CodigosRechazo.CodigoRechazo map ((o, i) -> o)
                            },
                            Numero: it.Numero
                        })
                    }) if (!isEmpty(vars.mensajeAbdFinal.MensajeABD.CuerpoMensaje.RespuestaSolicitudNIP.NumeracionRechazada)),
                    RespuestaABD: vars.mensajeAbdFinal.MensajeABD.CuerpoMensaje.RespuestaSolicitudNIP.RespuestaABD
                }
            }
        }
    }
}

// 0004
else if (vars.mensajeAbdFinal.MensajeABD.CabeceraMensaje.TipoMsg == "0004")
{
    WSRequestSolicitudSincronizacionABD: {
        PortabilidadMsg: {
            CabeceraMensaje: {
                Identificador: vars.idIntegration,
                TipoDeMensaje: vars.mensajeAbdFinal.MensajeABD.CabeceraMensaje.TipoMsg
            },
            CuerpoMensaje: {
                RespuestaSolicitudPortacionDonante: {
                    (ListaNumeracionRechazada: {
                        NumeracionRechazada: [{
                            CodigosRechazo: {
                                CodigoRechazo: vars.mensajeAbdFinal.MensajeABD.CuerpoMensaje.RespuestaSolicitudReenvioNIP.CodigosRechazo.CodigoRechazo map ((o, i) -> o)
                            }
                        }]
                    }) if (!isEmpty(vars.mensajeAbdFinal.MensajeABD.CuerpoMensaje.RespuestaSolicitudReenvioNIP.CodigosRechazo)),
                    RespuestaABD: vars.mensajeAbdFinal.MensajeABD.CuerpoMensaje.RespuestaSolicitudReenvioNIP.RespuestaABD
                }
            }
        }
    }
}

//1002
else if (vars.mensajeAbdFinal.MensajeABD.CabeceraMensaje.TipoMsg == "1002")
{
    WSRequestPortabilidadSaliente: {
        PortabilidadMsg: {
            CabeceraMensaje: {
                Identificador: vars.idIntegration
            },
            CuerpoMensaje: {
                RespuestaSolicitudPortacionDonante: {
                    DireccionAbonado: vars.mensajeAbdFinal.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.DireccionAbonado,
                    DocumentoAT: vars.mensajeAbdFinal.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.DocumentoAT,
                    DocumentoCC: vars.mensajeAbdFinal.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.DocumentoCC,
                    DocumentoID: vars.mensajeAbdFinal.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.DocumentoID,
                    IdentificacionAbonado: vars.mensajeAbdFinal.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.IdentificacionAbonado,
                    ListaNumeracionNip: {
                        NumeracionNip: vars.mensajeAbdFinal.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.ListaNumeracionNip.NumeracionNip map ((o, i) -> {
                            Numero: o.Numero,
                            FechaCreacionNIP: o.FechaCreacionNIP
                        })
                    },
                    NombreRazonSocialAbonado: vars.mensajeAbdFinal.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.NombreRazonSocialAbonado,
                    NRN: vars.mensajeAbdFinal.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.NRN,
                    SolicitudTerceros: vars.mensajeAbdFinal.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.SolicitudTerceros,
                    TipoServicio: vars.mensajeAbdFinal.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.TipoServicio,
                    TipoUsuario: vars.mensajeAbdFinal.MensajeABD.CuerpoMensaje.ReplicaSolicitudPortacion.TipoUsuario
                }
            }
        }
    }
}

//1004
else if (vars.mensajeAbdFinal.MensajeABD.CabeceraMensaje.TipoMsg == "1004")
{
    WSRequestSolicitudSincronizacionABD: {
        PortabilidadMsg: {
            CabeceraMensaje: {
                Identificador: vars.idIntegration,
                TipoDeMensaje: vars.mensajeAbdFinal.MensajeABD.CabeceraMensaje.TipoMsg
            },
            CuerpoMensaje: {
                RespuestaSolicitudPortacionDonante: {
                    (ListaNumeracionRechazada: {
                        NumeracionRechazada: vars.mensajeAbdFinal.MensajeABD.CuerpoMensaje.ReplicaRespuestaSolicitudPortacionDonante.ListaNumeracionRechazada.NumeracionRechazada map ((it, in) -> {
                            CodigosRechazo: {
                                CodigoRechazo: it.CodigosRechazo.CodigoRechazo map ((o, i) -> o)
                            },
                            (DocumentoDC: it.DocumentoDC) if (!isEmpty(it.DocumentoDC)),
                            (DocumentoFC: it.DocumentoFC) if (!isEmpty(it.DocumentoFC)),
                            (DocumentoFR: it.DocumentoFR) if (!isEmpty(it.DocumentoFR)),
                            (DocumentoUO: it.DocumentoUO) if (!isEmpty(it.DocumentoUO)),
                            Numero: it.Numero
                        })
                    }) if (!isEmpty(vars.mensajeAbdFinal.MensajeABD.CuerpoMensaje.ReplicaRespuestaSolicitudPortacionDonante.ListaNumeracionRechazada.NumeracionRechazada)),
                    RespuestaABD: vars.mensajeAbdFinal.MensajeABD.CuerpoMensaje.ReplicaRespuestaSolicitudPortacionDonante.RespuestaABD
                }
            }
        }
    }
}

//1005
else if (vars.mensajeAbdFinal.MensajeABD.CabeceraMensaje.TipoMsg == "1005")
{
    WSRequestSolicitudSincronizacionABD: {
        PortabilidadMsg: {
            CabeceraMensaje: {
                Identificador: vars.idIntegration,
                TipoDeMensaje: vars.mensajeAbdFinal.MensajeABD.CabeceraMensaje.TipoMsg
            },
            CuerpoMensaje: {
                FechaMaxVentanaCambio: if (!isEmpty(vars.mensajeAbdFinal.MensajeABD.CuerpoMensaje.SolicitudDeProgramacionPortacion.FechaVentanaMaxima)) substring(vars.mensajeAbdFinal.MensajeABD.CuerpoMensaje.SolicitudDeProgramacionPortacion.FechaVentanaMaxima, 4, 6) ++ "/" ++ substring(vars.mensajeAbdFinal.MensajeABD.CuerpoMensaje.SolicitudDeProgramacionPortacion.FechaVentanaMaxima, 6, 8) ++ "/"  ++ substring(vars.mensajeAbdFinal.MensajeABD.CuerpoMensaje.SolicitudDeProgramacionPortacion.FechaVentanaMaxima, 0, 4) else null
            }
        }
    }
}

//1007
else if (vars.mensajeAbdFinal.MensajeABD.CabeceraMensaje.TipoMsg == "1007")
{
    WSRequestSolicitudSincronizacionABD: {
        PortabilidadMsg: {
            CabeceraMensaje: {
                Identificador: vars.idIntegration,
                TipoDeMensaje: vars.mensajeAbdFinal.MensajeABD.CabeceraMensaje.TipoMsg
            },
            CuerpoMensaje: {
                FechaVentanaConfirmada: if (!isEmpty(vars.mensajeAbdFinal.MensajeABD.CuerpoMensaje.ConfirmacionProgramacionPortacion.FechaVentanaCambio)) substring(vars.mensajeAbdFinal.MensajeABD.CuerpoMensaje.ConfirmacionProgramacionPortacion.FechaVentanaCambio, 4, 6) ++ "/" ++ substring(vars.mensajeAbdFinal.MensajeABD.CuerpoMensaje.ConfirmacionProgramacionPortacion.FechaVentanaCambio, 6, 8) ++ "/"  ++ substring(vars.mensajeAbdFinal.MensajeABD.CuerpoMensaje.ConfirmacionProgramacionPortacion.FechaVentanaCambio, 0, 4) else null
            }
        }
    }
}

//9998
else if (vars.mensajeAbdFinal.MensajeABD.CabeceraMensaje.TipoMsg == "9998")
{
    WSRequestSolicitudSincronizacionABD: {
        PortabilidadMsg: {
            CabeceraMensaje: {
                Identificador: vars.idIntegration,
                TipoDeMensaje: vars.mensajeAbdFinal.MensajeABD.CabeceraMensaje.TipoMsg
            },
            CuerpoMensaje: {
                TipoErrorDetectadoABD: {
                    CodigosRechazo: {
                        CodigoRechazo: vars.mensajeAbdFinal.MensajeABD.CuerpoMensaje.ErrorDetectadoABD.CodigosRechazo.CodigoRechazo map ((item, index) -> {
                            TipoCodigoCausa: item
                        })
                    },
                    IdentificadorMensajeErroneo: {
                            IdentificadorMensajeErroneo: vars.mensajeAbdFinal.MensajeABD.CuerpoMensaje.ErrorDetectadoABD.IdentificadorMensajeErroneo
                        }
                }
            }
        }
    }
}

//9999
else if (vars.mensajeAbdFinal.MensajeABD.CabeceraMensaje.TipoMsg == "9999")
{
    WSRequestSolicitudSincronizacionABD: {
        PortabilidadMsg: {
            CabeceraMensaje: {
                Identificador: vars.idIntegration,
                TipoDeMensaje: vars.mensajeAbdFinal.MensajeABD.CabeceraMensaje.TipoMsg
            },
            CuerpoMensaje: {
                NumeracionesRechazadas: {
                    NumeracionesRechazadas: {
                        NumeracionRechazada: vars.mensajeAbdFinal.MensajeABD.CuerpoMensaje.RechazoPortacion.NumeracionesRechazadas.NumeracionRechazada map ((item, index) -> {
                            CodigosRechazo: {
                                CodigoRechazo: item.CodigosRechazo.CodigoRechazo map ((it, in) -> {
                                    TipoCodigoCausa: it
                                })
                            },
                            Numero: {
                                TipoNumero: item.Numero
                            }
                        })
                    }
                }
            }
        }
    }
}
else {}

%dw 2.0
output application/json
---
if (payload.status == "OK" and vars.notificationMDM.resultado.code == "0")
{
    "receiveMessageResponse": {
      "receiveMessageReturn": "ack"
    }
}
else
{
    "receiveMessageResponse": {
      "receiveMessageReturn": "nack"
    }
}
